```cpp
#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    std::string html;
    std::string line;
    std::istringstream stream(markdown);

    while (std::getline(stream, line)) {
        html += line + "\n";
    }

    return html;
}

int main() {
    std::string markdown = "# Heading\n\nThis is a sample paragraph.\n\n* "
                          "Bullet\n* List\n\nCode\n```\nBlock\n```\n";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

